const lv_img_dsc_t* ks_icon(const char* name, int px) {
  for (const ks_icon_entry* e = ks_icon_table; e->name; e++) {
    if (strcmp(e->name, name)) continue;
    const lv_img_dsc_t* best = nullptr;
    for (const ks_icon_size& s : e->sizes) { if (!s.img) break; best = s.img; if (s.px >= px) break; }
    return best;
  }
  return nullptr;
}
